"""The dependency audit skips private packages and reports both ecosystems."""

from __future__ import annotations

import importlib.util
import re
from pathlib import Path
from types import ModuleType

import pytest

ROOT = Path(__file__).parent.parent


def _load() -> ModuleType:
    spec = importlib.util.spec_from_file_location("dep_audit", ROOT / "scripts" / "dep_audit.py")
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


EXPORTED = """\
# This file was autogenerated by uv
pdomain-book-tools==0.28.0
    # via pdomain-prep-for-pgdp
Pdomain_Ops==0.11.2
pillow==12.3.0
    # via pdomain-book-tools
colorama==0.4.6 ; sys_platform == 'win32'
"""


def test_public_requirements_drops_private_packages_and_comments() -> None:
    assert _load().public_requirements(EXPORTED) == (
        "pillow==12.3.0\ncolorama==0.4.6 ; sys_platform == 'win32'\n"
    )


def test_public_requirements_keeps_a_name_that_only_contains_pdomain() -> None:
    assert _load().public_requirements("notpdomain-x==1.0\n") == "notpdomain-x==1.0\n"


@pytest.mark.parametrize(
    ("python_status", "frontend_status", "expected"),
    [(0, 0, 0), (1, 0, 1), (0, 1, 1), (1, 1, 1)],
)
def test_overall_status_fails_when_either_audit_fails(
    python_status: int, frontend_status: int, expected: int
) -> None:
    assert _load().overall_status(python_status, frontend_status) == expected


def test_make_audit_target_runs_the_script() -> None:
    match = re.search(r"^audit:.*\n\t(.*)$", (ROOT / "Makefile").read_text(), flags=re.MULTILINE)
    assert match is not None
    assert "scripts/dep_audit.py" in match.group(1)
